def bench(label, n = 100)
  t0 = Process.clock_gettime(Process::CLOCK_MONOTONIC)
  queries = 0
  sub = ActiveSupport::Notifications.subscribe("sql.active_record") { |*, p| queries += 1 unless p[:name] == "SCHEMA" }
  ActiveRecord::Base.transaction do
    n.times { |i| yield(i) }
    raise ActiveRecord::Rollback
  end
  ActiveSupport::Notifications.unsubscribe(sub)
  dt = Process.clock_gettime(Process::CLOCK_MONOTONIC) - t0
  puts format("%-45s %6.2f ms total (%5.2f ms/call, %5.1f queries/call)", label, dt * 1000, dt * 1000 / n, queries.to_f / n)
end

# Warmup
ActiveRecord::Base.transaction do
  Fabricate(:account); Fabricate(:user); Fabricate(:status)
  raise ActiveRecord::Rollback
end

