# frozen_string_literal: true

RSpec.shared_context 'with API authentication' do |oauth_scopes: '', user_fabricator: :user, with_application: false|
  let_it_be(:api_auth_user) { Fabricate(user_fabricator) }
  if with_application
    let_it_be(:client_app)     { Fabricate(:application, name: 'Test app', website: 'http://testapp.com') }
    let_it_be(:api_auth_token) { Fabricate(:accessible_access_token, resource_owner_id: api_auth_user.id, application: client_app, scopes: oauth_scopes) }
  else
    let_it_be(:api_auth_token) { Fabricate(:accessible_access_token, resource_owner_id: api_auth_user.id, scopes: oauth_scopes) }
  end
  let_it_be(:user) { api_auth_user }

  if user_fabricator != :user
    let_it_be(:api_auth_no_role_user)        { Fabricate(:user) }
    let_it_be(:api_auth_no_role_token)       { Fabricate(:accessible_access_token, resource_owner_id: api_auth_no_role_user.id, scopes: oauth_scopes) }
    let_it_be(:api_auth_moderator_role_user) { Fabricate(:moderator_user) }
    let_it_be(:api_auth_moderator_token)     { Fabricate(:accessible_access_token, resource_owner_id: api_auth_moderator_role_user.id, scopes: oauth_scopes) }
  end

  let(:scopes) { oauth_scopes }
  let(:token) do
    app = with_application ? client_app : nil
    if user&.id == api_auth_user.id && scopes == oauth_scopes
      api_auth_token
    elsif respond_to?(:api_auth_no_role_user) && user&.id == api_auth_no_role_user.id && scopes == oauth_scopes && app.nil?
      api_auth_no_role_token
    elsif respond_to?(:api_auth_moderator_role_user) && user&.id == api_auth_moderator_role_user.id && scopes == oauth_scopes && app.nil?
      api_auth_moderator_token
    else
      Fabricate(:accessible_access_token, resource_owner_id: user&.id, application: app, scopes: scopes)
    end
  end
  let(:headers) { { 'Authorization' => "Bearer #{token.token}" } }
end
EOF

